// ---- Services ----

/**
 * RequestService sends HTTP requests for the debug page and picks files for it.
 * Every exported method here is bound to the frontend, so helpers stay unexported.
 */
export const RequestService = {
  /**
   * PickFile asks the user for a file and returns its path, or "" when they
   * cancel the dialog.
   */
  pickFile: bind<[], string>("RequestService.PickFile", () => []),
  /**
   * Send performs req and returns the response, along with what was actually sent.
   * An event stream arrives on stream instead of in the body.
   */
  send: bind<[APIRequest, Channel<SSEMessage>], APIResponse>("RequestService.Send", (req: APIRequest, stream: Channel<SSEMessage>) => [req, stream]),
} as const;

/**
 * WorkspaceService reads and writes the .band workspaces the page keeps.
 * Every exported method here is bound to the frontend, so helpers stay unexported.
 */
export const WorkspaceService = {
  /**
   * AskSavePath asks where to write a workspace and returns the path, or "" when
   * the user cancels the dialog: 加密与否由后续的 Save 参数决定，这里只挑位置。
   */
  askSavePath: bind<[string], string>("WorkspaceService.AskSavePath", (name: string) => [name]),
  /**
   * CloseWindow closes the window even though the workspace may hold unsaved
   * changes, once the page's user chose to discard them.
   */
  closeWindow: bind<[], void>("WorkspaceService.CloseWindow", () => []),
  /**
   * DismissTrust 丢弃挂起的读盘（用户选了取消）：没解析的内容一并丢掉，
   * 什么都不写盘。
   */
  dismissTrust: bind<[], void>("WorkspaceService.DismissTrust", () => []),
  /**
   * Open asks for a .band file and returns the workspace in it, or a zero
   * WorkspaceOpen when the user cancels the dialog.
   */
  open: bind<[], WorkspaceOpen>("WorkspaceService.Open", () => []),
  /**
   * OpenPath reads the .band workspace at path, which the page got from a
   * dropped file rather than the dialog: the path is known, so Save writes the
   * workspace back to it.
   */
  openPath: bind<[string], WorkspaceOpen>("WorkspaceService.OpenPath", (path: string) => [path]),
  /**
   * ResolveTrust 是信任弹窗的答复：remember=false 是「信任一次」（只在这次打开
   * 生效），true 是「信任公钥」（写进 trusted.json）。指纹不匹配或没有挂起的读盘
   * 都报错——挂起槽只消费一次，宁可让用户重开，也不让别人的公钥过关。
   */
  resolveTrust: bind<[string, boolean], WorkspaceFile>("WorkspaceService.ResolveTrust", (fingerprint: string, remember: boolean) => [fingerprint, remember]),
  /**
   * Save writes data over the workspace at path. 加密与否、写给谁由 opts 决定：
   * 加密 + 指定收件人 = 新信封；加密 + 不指定 = 沿用已载入的信封；否则写明文。
   * 保存者永远用自己的身份签名。
   */
  save: bind<[string, WorkspaceData, SaveOptions], void>("WorkspaceService.Save", (path: string, data: WorkspaceData, opts: SaveOptions) => [path, data, opts]),
  /**
   * SetDirty tells the window whether the workspace holds unsaved changes: while
   * it does, closing the window asks the page before going ahead.
   */
  setDirty: bind<[boolean], void>("WorkspaceService.SetDirty", (dirty: boolean) => [dirty]),
} as const;

/**
 * SocketService opens WebSocket, TCP and Socket.IO connections the page talks
 * over. The connections themselves live in backend/protocol; this shell maps
 * the page's contract types onto it, and runs the connection's scripts around
 * what it asks the protocol package to do. Every exported method here is bound
 * to the frontend, so helpers stay unexported.
 */
export const SocketService = {
  /**
   * Connect opens the connection params names and stays until it closes or the
   * page disconnects it, pushing what happens on stream as it happens.
   */
  connect: bind<[SocketConnectParams, Channel<SocketEvent>], void>("SocketService.Connect", (params: SocketConnectParams, stream: Channel<SocketEvent>) => [params, stream]),
  /**
   * Disconnect closes the connection id names; an id that is already gone is not
   * an error.
   */
  disconnect: bind<[string], void>("SocketService.Disconnect", (id: string) => [id]),
  /** Send writes one message to the connection params.ID names. */
  send: bind<[SocketSendParams], void>("SocketService.Send", (params: SocketSendParams) => [params]),
} as const;

/**
 * GrpcService lists and calls the gRPC methods of a target. The connections
 * themselves live in backend/protocol; this shell maps the page's contract types
 * onto it. Every exported method here is bound to the frontend, so helpers stay
 * unexported.
 */
export const GrpcService = {
  /**
   * CloseSend half-closes the request stream of the call id names, so the server
   * knows no more messages follow; the call keeps receiving until it completes.
   */
  closeSend: bind<[string], void>("GrpcService.CloseSend", (id: string) => [id]),
  /**
   * Connect opens the call params.ID names and stays until it completes or the
   * page disconnects it, pushing what happens on stream as it happens.
   */
  connect: bind<[GrpcConnectParams, Channel<GrpcEvent>], void>("GrpcService.Connect", (params: GrpcConnectParams, stream: Channel<GrpcEvent>) => [params, stream]),
  /** Disconnect ends the call id names; an id that is already gone is not an error. */
  disconnect: bind<[string], void>("GrpcService.Disconnect", (id: string) => [id]),
  /**
   * List asks params.Target what it serves: through server reflection, or through
   * the local .proto files params.ProtoFiles names.
   */
  list: bind<[GrpcListParams], GrpcServiceInfo[]>("GrpcService.List", (params: GrpcListParams) => [params]),
  /** Send writes one request message to the streaming call id names. */
  send: bind<[string, string], void>("GrpcService.Send", (id: string, payload: string) => [id, payload]),
} as const;

/**
 * ComposerService runs composer scripts: one goja script that calls the
 * workspace's own requests through nd.composer.run, one after another, sharing
 * one variable pool. Every exported method here is bound to the frontend, so
 * helpers stay unexported.
 */
export const ComposerService = {
  /**
   * Run performs one run, pushing what happens on stream as it happens. The result
   * carries the counts and — when the run did not finish normally — why; an error
   * is reserved for a run that could not start at all.
   */
  run: bind<[ComposerRunParams, Channel<ComposerEvent>], ComposerResult>("ComposerService.Run", (params: ComposerRunParams, stream: Channel<ComposerEvent>) => [params, stream]),
  /**
   * Stop ends the run id names: the script is interrupted and the request it is
   * waiting on is cancelled. An id that is already gone is not an error.
   */
  stop: bind<[string], void>("ComposerService.Stop", (id: string) => [id]),
} as const;

/**
 * ScriptService 暴露脚本运行与页面之间的交互。Every exported method here is
 * bound to the frontend, so helpers stay unexported.
 */
export const ScriptService = {
  /**
   * ResolveInput 回答一次 nd.input：value 写进脚本要的变量，ok=false 表示用户取消。
   * 不存在或已回答的 id 静默忽略（与 Stop/Disconnect 的幂等语义一致）。
   */
  resolveInput: bind<[string, string, boolean], void>("ScriptService.ResolveInput", (id: string, value: string, ok: boolean) => [id, value, ok]),
} as const;

/**
 * AppService 暴露应用自身的信息与桌面集成能力。
 * Every exported method here is bound to the frontend, so helpers stay unexported.
 */
export const AppService = {
  /**
   * OpenURL 用系统默认应用打开 URL：设置页「关于」里的 GitHub 主页链接
   * 经它在用户的外部浏览器里打开，而不是应用内 webview。
   */
  openURL: bind<[string], void>("AppService.OpenURL", (url: string) => [url]),
  /** Version 返回应用版本号（来自打包信息，即 mygo.config.ts 里的 version）。 */
  version: bind<[], string>("AppService.Version", () => []),
} as const;

/**
 * IdentityService 是本机身份与信任列表的入口。
 * Every exported method here is bound to the frontend, so helpers stay unexported.
 */
export const IdentityService = {
  /** Candidates 是加密保存时的收件人候选：自己、持久信任、身份缓存，按指纹去重。 */
  candidates: bind<[], IdentityCandidate[]>("IdentityService.Candidates", () => []),
  /** Get 返回当前身份；还没建立时 status 是 "unset"。 */
  get: bind<[], IdentityInfo>("IdentityService.Get", () => []),
  /**
   * ImportFromBand 从一个 .band 的 header 里导入签发者公钥：加密的 band 也能导
   * （头和身份恒为明文），但只读头、不信任、不解密。
   */
  importFromBand: bind<[], IdentityCandidate>("IdentityService.ImportFromBand", () => []),
  /**
   * Setup 首次运行建立身份：ed25519 签名密钥对 + X25519 密钥对。email 留空时
   * 随机取「形容词的+名词」@主机名。已经建立过就原样返回，不重建密钥——
   * 换密钥等于换一个身份，别人签给旧身份的信任和加密文件会全部失效。
   */
  setup: bind<[string], IdentityInfo>("IdentityService.Setup", (email: string) => [email]),
  /** Trusted 返回持久信任列表。 */
  trusted: bind<[], TrustedIdentity[]>("IdentityService.Trusted", () => []),
  /**
   * Untrust 从持久信任列表里移除一个指纹，同时清掉本次进程里的「信任一次」。
   * 移除失败（文件写不了）时列表保持原样：下次读到的还是旧的一份。
   */
  untrust: bind<[string], void>("IdentityService.Untrust", (fingerprint: string) => [fingerprint]),
  /**
   * Update 只改展示信息（email / id）：指纹与密钥不变，旧签名包的验证不受影响。
   * 空串表示这一项不动。
   */
  update: bind<[string, string], IdentityInfo>("IdentityService.Update", (email: string, id: string) => [email, id]),
} as const;

// ---- Events ----

/** Events sent by the Go side. Subscribe with `events.name.on(listener)`. */
export const events = {
  /**
   * closeRequested asks the page whether it is fine to close the window: it goes
   * out when the user closes a window whose workspace holds unsaved changes, and
   * the page answers with WorkspaceService.SetDirty (now clean) or
   * WorkspaceService.CloseWindow (discard the changes).
   */
  workspaceCloseRequested: event<boolean>("workspace:closeRequested"),
  /**
   * scriptInputRequested 请页面为一次 nd.input 弹出输入框：脚本阻塞在 Go 侧等回答，
   * 页面弹模态框，用户确认或取消后经 ScriptService.ResolveInput 回来。
   */
  scriptInputRequested: event<ScriptInputRequest>("script:inputRequested"),
  /**
   * scriptInputRetracted 收回一个还开着的输入框：等回答的运行已经结束（页面关闭、
   * composer 终止），负载是那次输入请求的 id。回答与撤回撞车时页面两个都认得：
   * 已回答的框不在了就忽略撤回，没回答的框被撤回后回答也递不到（幂等丢弃）。
   */
  scriptInputRetracted: event<string>("script:inputRetracted"),
} as const;
